def review_pipeline(draft_spec, verified_claim_kg, jurisdiction):
    # Do not evaluate open generation post-hoc; restrict generation to slotted claim graphs
    content_ir = compile_to_claim_dag(draft_spec, verified_claim_kg)
    draft_asset = generate_within_dag_bounds(content_ir)
    # Syntactic checks are trivial; semantic drift from approved substantiation is where liability lives
    drift_risk = measure_claim_entailment(draft_asset, content_ir.source_nodes)
    # Assume downstream ad servers will strip C2PA headers; burn disclosure into rendering
    render_hardcoded_transparency_layer(draft_asset, jurisdiction.disclosure_rules)
    # Never let an LLM sign off on regulated claims; automate rejection and routing, not final clearance
    if drift_risk > 0.0 or requires_statutory_mlr(content_ir):
        return route_to_counsel(draft_asset, diff=content_ir.unmapped_tokens)
    return stage_for_canary_rollout(draft_asset, audit_sample_rate=0.10)

